func (s *service) AuthenticateClient(ctx context.Context, clientID, clientSecret string) error {
	_, err := s.client(ctx, clientID, clientSecret, true)
	return err
}

func (r *MemoryClientRegistry) RotateSecret(_ context.Context, id string, secretHash []byte) error {
	if len(secretHash) == 0 {
		return errors.New("oauth: a rotation needs a secret hash")
	}
	r.mu.Lock()
	defer r.mu.Unlock()
	c, ok := r.byID[id]
	if !ok {
		return ErrClientNotFound
	}
	if c.Type != ClientConfidential {
		return ErrNoSecretToRotate
	}

func (s *service) record(ctx context.Context, action, subject, clientID, outcome string) {
	_ = s.audit.Record(ctx, audit.Event{
		Action:   action,
		Subject:  subject,
		Provider: "oauth",
		Outcome:  outcome,
		Detail:   map[string]string{"client_id": clientID},
	})
}

func NewSecretHash(secret string) []byte {
	sum := sha256.Sum256([]byte(secret))
	return sum[:]
}

func (s *MemoryStore) GetAccess(_ context.Context, value string) (AccessToken, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	t, ok := s.access[TokenHash(value)]
	if !ok {
		return AccessToken{}, ErrTokenNotFound
	}
	return t, nil
}

func LimitFormBody(w http.ResponseWriter, r *http.Request) error {
	// A negative length means "unknown" — a chunked body — so this comparison is
	// false there and the cap is enforced while reading instead.
	if r.ContentLength > MaxFormBytes {
		return ErrBodyTooLarge
	}
	r.Body = http.MaxBytesReader(w, r.Body, MaxFormBytes)
	return nil
}
